from lib import *
S = SS('x50')
steps = [
    step("什么都不配置。带 Origin: https://a.example 的 GET /plain → 200,响应里没有任何 Access-Control-* 头;不带 Origin 的 → 200;预检 OPTIONS /plain(Origin 加 Access-Control-Request-Method: GET)→ 200,同样没有 CORS 头。服务端并不拒绝请求,方法照常执行、数据照常返回,拦住读取的是浏览器——它看到没有 Allow-Origin 就不让页面脚本读(浏览器这一步这里没有测,只测了服务端的响应头)。CORS 不是服务端的访问控制,不能拿它防别人直接调接口。", t=tl(S(1)), mark=lidx(S(1), '(没有)'), done=lidx(S(1), 'GET /plain  [Origin', 'OPTIONS /plain'), b=bars([['带 Origin 的 GET 状态码', 200, '200'], ['预检状态码', 200, '200'], ['响应里的 CORS 头个数', 0, '0']], 200, done=[0, 1], mark=[2]), kv=KV([['无配置', '请求照常处理,没有 CORS 头'], ['谁来拦', '浏览器看响应头决定是否让脚本读'], ['服务端', '不拒绝,不是访问控制'], ['直接调用', 'curl 等不受 CORS 影响']], ['服务端'])),
    step("@CrossOrigin(origins=a.example) 在单个方法上。a.example 的 GET → 200,响应带 Access-Control-Allow-Origin: https://a.example,Vary 里有 Origin、Access-Control-Request-Method、Access-Control-Request-Headers 三项。evil.example 的 GET → 403 “Invalid CORS request”,方法没有执行。不带 Origin → 200,没有 Allow-Origin;Origin 是服务自己的地址(http://127.0.0.1:端口,同源)→ 200,也没有 Allow-Origin,不被当作跨域拦截。预检:a.example 的 GET → 200,带 Allow-Origin、Allow-Methods: GET、Max-Age: 1800(没写 maxAge 时的默认);evil.example → 403;请求方法 DELETE(/ann 不支持)→ 200 但没有 CORS 头。", t=tl(S(2)), mark=lidx(S(2), 'evil.example', 'Req-Method: DELETE'), done=lidx(S(2), 'GET /ann  [Origin: https://a.example] → 200', 'OPTIONS /ann  [Origin: https://a.example Req-Method: GET]', 'http://127.0.0.1'), b=bars([['允许的来源 GET 状态码', 200, '200'], ['不允许的来源 GET 状态码', 403, '403'], ['预检默认 Max-Age 秒', 1800, '1800']], 1800, done=[0, 2], mark=[1]), kv=KV([['不在白名单的来源', '403 Invalid CORS request,方法不执行'], ['同源 Origin', '不算跨域,不加头也不拦'], ['预检默认 Max-Age', '1800 秒'], ['不支持的方法', '预检 200 但没有 CORS 头']], ['不在白名单的来源'])),
    step("@CrossOrigin 的更多属性与默认值。/ann-put(allowedHeaders=X-Token,methods=GET、PUT,maxAge=600,allowCredentials=true,exposedHeaders=X-Total):预检 PUT + X-Token → 200,Allow-Methods: GET,PUT、Allow-Headers: X-Token、Expose-Headers: X-Total、Allow-Credentials: true、Max-Age: 600;请求头换成 X-Other → 403;真正的 PUT 请求只带 Allow-Origin、Expose-Headers、Allow-Credentials,不带 Methods 和 Max-Age。什么都不写的 @CrossOrigin(/open):实际请求 Allow-Origin: *;预检里 Allow-Headers 原样回显请求的 X-Whatever,Allow-Methods: GET,Max-Age: 1800。", t=tl(S(3)), mark=lidx(S(3), 'Req-Headers: X-Other', 'PUT /ann-put'), done=lidx(S(3), 'Req-Headers: X-Token', 'GET /open', 'OPTIONS /open'), b=bars([['/ann-put 预检 Max-Age 秒', 600, '600'], ['/open 预检 Max-Age 秒', 1800, '1800(默认)'], ['不允许的头 X-Other 的状态码', 403, '403']], 1800, done=[0, 1], mark=[2]), kv=KV([['allowCredentials=true', 'Allow-Credentials: true'], ['实际请求', '只带 Origin / Expose / Credentials'], ['预检', '才带 Methods / Headers / Max-Age'], ['空的 @CrossOrigin', '任意来源 *,请求头回显']], ['预检'])),
    step("全局配置(WebMvcConfigurer.addCorsMappings)。/api/** 允许 https://b.example、GET 和 POST、任意头、maxAge=120:预检 POST + Content-Type → 200,Allow-Methods: GET,POST、Allow-Headers: Content-Type、Max-Age: 120;预检 DELETE → 403;实际 GET → Allow-Origin: https://b.example。/plain 用 allowedOriginPatterns(https://*.example)并 allowCredentials:来源 sub.example → Allow-Origin 回显 https://sub.example(不是 *),Allow-Credentials: true;a.other → 403。方法上的 @CrossOrigin 照常生效(/ann 仍是 a.example)。/api/boom 抛异常 → 500,但响应里仍有 Allow-Origin: https://b.example。", t=tl(S(4)), mark=lidx(S(4), 'Req-Method: DELETE', 'a.other'), done=lidx(S(4), 'Req-Method: POST', 'sub.example', '/api/boom'), b=bars([['预检 POST 状态码', 200, '200'], ['预检 DELETE 状态码', 403, '403'], ['/api/boom 状态码', 500, '500(仍带 Allow-Origin)']], 500, done=[0, 2], mark=[1]), kv=KV([['allowedOriginPatterns', '通配子域名,回显来源而不是 *'], ['带凭据', '不能返回 *,只能回显具体来源'], ['全局 + 注解', '各管各的路径,注解仍生效'], ['处理器里抛异常', 'CORS 头已经设好,500 响应里仍然有']], ['带凭据'])),
    step("CorsFilter(放在最前面,order 最小)。https://f.example:/boom 抛异常 → 500,响应有 Allow-Origin: https://f.example;不存在的 /nope → 404,也有 Allow-Origin;预检 POST + X-Any → 200,带 Allow-Methods: POST 和 Allow-Headers: X-Any;other.example → 403 “Invalid CORS request”。Filter 在 DispatcherServlet 之前,不管后面有没有处理器、会不会出错,都按同一份配置加头,所以 404 和路径不存在的请求也被覆盖。", t=tl(S(5)), mark=lidx(S(5), 'GET /nope', 'other.example'), done=lidx(S(5), 'GET /boom  [Origin: https://f.example]', 'OPTIONS /boom'), b=bars([['/boom 500 带 Allow-Origin(1=是)', 1, '是'], ['/nope 404 带 Allow-Origin(1=是)', 1, '是'], ['other.example 的状态码', 403, '403']], 403, done=[0, 1], mark=[2]), kv=KV([['CorsFilter', '在 DispatcherServlet 之前,所有请求同一份规则'], ['404', '也带 CORS 头'], ['异常', '500 也带'], ['适用', '要覆盖 Spring MVC 管不到的路径时']], ['CorsFilter'])),
    step("对照:只有 @CrossOrigin 注解、没有全局配置时。没有注解的 /boom 抛异常 → 500,没有任何 CORS 头;不存在的 /nope → 404,没有 CORS 头;有注解的 /ann-boom 抛异常 → 500,但仍带 Allow-Origin: https://a.example。没有匹配 CORS 配置的路径,500 和 404 的响应里都没有 CORS 头,浏览器上看到的会是一个 CORS 错误,看不到真正的 500 或 404。", t=tl(S(6)), mark=lidx(S(6), 'GET /boom', 'GET /nope'), done=lidx(S(6), '/ann-boom'), b=bars([['/boom(无注解)500 带 CORS 头个数', 0, '0'], ['/nope 404 带 CORS 头个数', 0, '0'], ['/ann-boom 500 带 Allow-Origin(1=是)', 1, '是']], 1, mark=[0, 1], done=[2]), kv=KV([['没有匹配 CORS 配置的路径', '500、404 都不带头'], ['有匹配配置的路径', '异常的 500 仍带头'], ['浏览器看到', 'CORS 错误,看不到真实状态码'], ['排查', '先 curl 带 Origin 看响应头']], ['浏览器看到'])),
    step("配置错误。allowedOrigins(\"*\") 同时 allowCredentials(true):应用启动没有报错,请求到来时才出错——实际请求和预检请求都是 500,响应是 HTML 错误页,没有 CORS 头;服务端日志里是 IllegalArgumentException: When allowCredentials is true, allowedOrigins cannot contain the special value \"*\" …。启动成功不代表 CORS 配置是对的。", t=tl(S(7)), mark=lidx(S(7), 'When allowCredentials is true'), done=lidx(S(7), 'GET /plain', 'OPTIONS /plain'), b=bars([['实际请求状态码', 500, '500'], ['预检请求状态码', 500, '500'], ['响应里的 CORS 头个数', 0, '0']], 500, mark=[0, 1], done=[2]), kv=KV([['allowedOrigins("*") + allowCredentials(true)', '请求时抛 IllegalArgumentException'], ['启动', '没有报错'], ['响应', '500 HTML 错误页,无 CORS 头'], ['正确做法', '带凭据时改用 allowedOriginPatterns 或具体来源']], ['启动'])),
]
A = mkartx('x50', 50, 'Spring,MVC,CORS,CrossOrigin,预检请求,CorsFilter,真实验证,动画演示',
    '实测 Spring MVC 的 CORS:没有配置时服务端照常返回 200,拦截的是浏览器;@CrossOrigin 不在白名单的来源得到 403 Invalid CORS request;预检默认 Max-Age 1800,实际请求只带 Origin、Expose、Credentials 头;全局 addCorsMappings 与 allowedOriginPatterns 回显来源;异常的 500 在有匹配配置时仍带 CORS 头,没有匹配配置的路径(含 404)不带;CorsFilter 能覆盖 404;allowedOrigins("*") 加 allowCredentials(true) 启动不报错、请求时 500。',
    '浏览器报 CORS 错误,服务端到底返回了什么?预检请求和真正的请求分别带哪些头?@CrossOrigin、addCorsMappings、CorsFilter 三个位置有什么区别?为什么 500 和 404 在浏览器里总是变成 CORS 错误?这篇在 Spring Boot 4.0.8 上用手工带 Origin 的请求逐个看响应头。',
    [('403', '不在白名单的来源,实际请求和预检请求都被拒绝,方法不执行'), ('1800', '没写 maxAge 时预检响应的默认 Access-Control-Max-Age(秒)'), ('0', '没有匹配 CORS 配置的路径上,500 和 404 响应里的 CORS 头个数')],
    [('无配置', '<p>服务端照常返回,拦住读取的是浏览器;CORS 不是访问控制。</p>'),
     ('@CrossOrigin', '<p>白名单外的来源 403;预检与实际请求带的头不同;同源不算跨域。</p>'),
     ('属性与默认值', '<p>maxAge 默认 1800;空注解允许任意来源。</p>'),
     ('全局配置', '<p>allowedOriginPatterns 回显来源;注解仍然生效。</p>'),
     ('CorsFilter', '<p>在 DispatcherServlet 前,404 和异常响应都带头。</p>'),
     ('没有配置的路径', '<p>没有匹配 CORS 配置的路径上,500 和 404 不带 CORS 头。</p>'),
     ('配置错误', '<p>allowedOrigins("*") 加 allowCredentials(true) 启动不报错,请求时 500。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的 SpringApplication(spring-boot-starter-webmvc,内嵌 Tomcat 11.0.24);请求由 Python 的 http.client 手工带 Origin、Access-Control-Request-* 头发出,表中的头名省略了 Access-Control- 前缀(Vary 的多个值合并显示);各配置位置用 @ConditionalOnProperty 按属性开关,分别启动应用',
     '没有验证:真实浏览器对这些响应头的处理(包括私有网络访问、缓存预检结果);Spring Security 开启后 CORS 与过滤器链的顺序(见 Security 章节);Access-Control-Allow-Private-Network;allowedOriginPatterns 的更复杂写法;WebFlux 的 CorsWebFilter;Origin: null 的处理'],
    'CORS')
